// Exact F2 subspace census and automorphism-orbit verification for (2,3) binary divisors.
// Input: whitespace-separated smooth 12-bit masks generated by verify_geometry.py.
#include <algorithm>
#include <array>
#include <cassert>
#include <fstream>
#include <iostream>
#include <map>
#include <set>
#include <string>
#include <vector>
using namespace std;
using Net=array<int,7>;
static int multiply(int a,int b){int c=0; for(int i=0;i<8;i++)if(a>>i&1)for(int j=0;j<8;j++)if(b>>j&1)c^=1<<(i+j);return c;}
static int power(int a,int k){int r=1;while(k--)r=multiply(r,a);return r;}
static vector<array<int,4>> gl2(){vector<array<int,4>>m;for(int a=0;a<2;a++)for(int b=0;b<2;b++)for(int c=0;c<2;c++)for(int d=0;d<2;d++)if((a*d^b*c)==1)m.push_back({a,b,c,d});return m;}
static array<int,12> transform(array<int,4>A,array<int,4>B){
 array<int,3>x;array<int,4>y;array<int,12>basis;
 for(int i=0;i<3;i++)x[i]=multiply(power(A[0]|A[1]<<1,2-i),power(A[2]|A[3]<<1,i));
 for(int j=0;j<4;j++)y[j]=multiply(power(B[0]|B[1]<<1,3-j),power(B[2]|B[3]<<1,j));
 for(int i=0;i<3;i++)for(int j=0;j<4;j++){int z=0;for(int a=0;a<3;a++)for(int b=0;b<4;b++)if((x[i]>>a&1)&&(y[j]>>b&1))z|=1<<(4*a+b);basis[4*i+j]=z;}
 return basis;
}
static int act(int v,const array<int,12>&g){int z=0;for(int i=0;i<12;i++)if(v>>i&1)z^=g[i];return z;}
static int eval(int v,int X0,int X1,int Y0,int Y1){int z=0;for(int i=0;i<3;i++)for(int j=0;j<4;j++)if(v>>(4*i+j)&1)z^=((i==2?X1: i==0?X0:(X0&X1))&(j==0?Y0:j==3?Y1:(Y0&Y1)));return z;}
int main(int argc,char**argv){if(argc<2){cerr<<"usage: verify_nets smooth_masks.txt\n";return 2;}
 ifstream in(argv[1]);vector<int> sm;int v;while(in>>v)sm.push_back(v);
 assert(sm.size()==1116);bool S[4096]={};for(int t:sm){assert(t>0&&t<4096&&!S[t]);S[t]=true;}
 long long pencils=0,extended=0;set<Net>nets;
 for(size_t i=0;i<sm.size();i++)for(size_t j=i+1;j<sm.size();j++){
  int a=sm[i],b=sm[j],c=a^b;if(!S[c]||b>c)continue;
  pencils++;
  for(int d:sm)if(d!=a&&d!=b&&d!=c&&S[a^d]&&S[b^d]&&S[c^d]){
   extended++;Net n={a,b,c,d,a^d,b^d,c^d};sort(n.begin(),n.end());nets.insert(n);
  }
 }
 assert(pencils==44070 && extended==250992 && nets.size()==8964);
 int admissible_four_extensions=0;
 for(const auto &n:nets)for(int d:sm){bool inside=false;for(int a:n)inside|=(d==a);if(inside)continue;
  bool ok=true;for(int a:n)if(!S[a^d]){ok=false;break;}
  if(ok)admissible_four_extensions++;
 }
 assert(admissible_four_extensions==0);
 vector<array<int,12>>group;auto m=gl2();for(auto a:m)for(auto b:m)group.push_back(transform(a,b));assert(group.size()==36);
 set<Net> seen;map<int,int> orbit_sizes;map<array<int,7>,int> spectra;
 for(const auto &n:nets){
  array<int,7>pt;
  for(int k=0;k<7;k++){
   int cnt=0;
   for(int x=0;x<3;x++)for(int y=0;y<3;y++){
    int x0=x==0||x==2,x1=x==1||x==2,y0=y==0||y==2,y1=y==1||y==2;
    cnt+=!eval(n[k],x0,x1,y0,y1);
   }
   pt[k]=cnt;
  }
  sort(pt.begin(),pt.end());spectra[pt]++;
  if(seen.count(n))continue;
  set<Net>orbit;
  for(auto g:group){Net t;for(int k=0;k<7;k++)t[k]=act(n[k],g);sort(t.begin(),t.end());assert(nets.count(t));orbit.insert(t);}
  for(auto t:orbit)seen.insert(t);
  orbit_sizes[(int)orbit.size()]++;
 }
 assert(seen.size()==nets.size());assert(orbit_sizes.size()==1&&orbit_sizes[36]==249&&spectra.size()==14);
 cout<<"smooth_forms 1116\npencils 44070\nnet_extensions 250992\nnets 8964\n4_space_extensions 0\nprojective_orbits 249\norbits_of_size_36 249\n";
 cout<<"spectra (point counts for 7 members): number_of_nets\n";
 for(auto [pt,n]:spectra){for(int v:pt)cout<<v<<",";cout<<" "<<n<<"\n";}
 cout<<"VERIFY_OK\n";
}
